        if ok.sum() < 20:
            continue
        tt, P = t[ok], P[ok]
        o = np.argsort(tt, kind="stable")
        tt, P = tt[o], P[o]
        keep = np.concatenate(([True], np.diff(tt) > 0))
        tt, P = tt[keep], P[keep]
        if tt.size < 20:
            continue
        span = float(tt[-1] - tt[0])
        if span <= 0:
