SEG_FINGER = {
    (1, 2): "Thumb", (2, 3): "Thumb", (3, 4): "Thumb",
    (5, 6): "Index", (6, 7): "Index", (7, 8): "Index",
    (9, 10): "Middle", (10, 11): "Middle", (11, 12): "Middle",
    (13, 14): "Ring", (13, 14): "Ring", (14, 15): "Ring", (15, 16): "Ring",
    (17, 18): "Pinky", (18, 19): "Pinky", (19, 20): "Pinky",
}
SEGMENTS = [(1, 2), (2, 3), (3, 4), (5, 6), (6, 7), (7, 8),
            (9, 10), (10, 11), (11, 12), (13, 14), (14, 15), (15, 16),
            (17, 18), (18, 19), (19, 20)]
FINGER_JOINTS = {"Thumb": [(0, 1, 2), (1, 2, 3)], "Index": [(5, 6, 7)], "Middle": [(9, 10, 11)],
                 "Ring": [(13, 14, 15)], "Pinky": [(17, 18, 19)]}
THRESH, MIN_SEG = 0.20, 2


def rd(p):
    with io.open(p, encoding="utf-8-sig") as fh:
        return list(csv.DictReader(fh))


def fl(x):
    try:
        v = float(x)
        return v if math.isfinite(v) else None
    except (TypeError, ValueError):
        return None


def interior(a, b, c):
    v1, v2 = a - b, c - b
    n1, n2 = np.linalg.norm(v1), np.linalg.norm(v2)
    if n1 < 1e-9 or n2 < 1e-9:
        return np.nan
    return math.degrees(math.acos(max(-1.0, min(1.0, float(np.dot(v1, v2) / (n1 * n2))))))


def load_windows(sd, hand):
    """(프레임배열 P, 원본 프레임 인덱스) 목록. 시간축=capture_monotonic_s."""
    out = []
    for lf in sorted(glob.glob(os.path.join(sd, "split", "*", "Trial_*", "*_landmarks.csv"))):
        if "pose_landmarks" in lf:
            continue
        df = lf.replace("_landmarks.csv", "_distance_comparison.csv")
        mono = {}
        if os.path.exists(df):
            for r in rd(df):
                if (r.get("Hand") or "") != hand:
                    continue
                fid, t = fl(r.get("Frame_ID")), fl(r.get("capture_monotonic_s"))
                if fid is not None and t is not None:
                    mono[int(fid)] = t
        by = {}
        with io.open(lf, encoding="utf-8-sig") as fh:
            for r in csv.DictReader(fh):
                if (r.get("Hand") or "").strip() != hand:
                    continue
                try:
                    fid = int(float(r["Frame_ID"])); lid = int(float(r["Landmark_ID"]))
                except (KeyError, TypeError, ValueError):
                    continue
                xyz = (fl(r.get("MP_X_m")), fl(r.get("MP_Y_m")), fl(r.get("MP_Z_m")))
                if all(v is not None for v in xyz):
                    by.setdefault(fid, {})[lid] = xyz
        if len(by) < 20:
            continue
        fids = [k for k in sorted(by) if all(0 <= l < 21 for l in by[k])]
        P = np.full((len(fids), 21, 3), np.nan)
        t = np.full(len(fids), np.nan)
        for i, fid in enumerate(fids):
            for lid, xyz in by[fid].items():
                if 0 <= lid <= 20:
                    P[i, lid] = xyz
            tv = mono.get(fid)
            if tv is not None:
                t[i] = tv
        good = np.isfinite(P[:, 0]).all(axis=1)
        P = P[good]
        if P.shape[0] < 20:
            continue
        out.append({"trial": os.path.basename(os.path.dirname(lf)), "P": P})
    return out


def seg_lengths(P):
    n = P.shape[0]
    L = np.full((n, len(SEGMENTS)), np.nan)
    for j, (a, b) in enumerate(SEGMENTS):
        L[:, j] = np.linalg.norm(P[:, a] - P[:, b], axis=-1)
    return L


def finger_theta(P):
    """손가락별 굴곡각 합 (deg), (n,5)."""
    flx = np.full((P.shape[0], 5), np.nan)
    for k, fg in enumerate(("Thumb", "Index", "Middle", "Ring", "Pinky")):
        acc = np.zeros(P.shape[0])
        cnt = np.zeros(P.shape[0])
        for (i1, i2, i3) in FINGER_JOINTS[fg]:
            for fr in range(P.shape[0]):
                v = 180.0 - interior(P[fr, i1], P[fr, i2], P[fr, i3])
                if np.isfinite(v):
                    acc[fr] += v
                    cnt[fr] += 1
        flx[:, k] = np.where(cnt > 0, acc / np.maximum(cnt, 1) * cnt, np.nan)
    return flx


def violations(L, Lhat):
    """프레임별 위반 분절 수. Lhat 은 (15,) 또는 (n,15)."""
    with np.errstate(invalid="ignore", divide="ignore"):
        rel = np.abs(L - Lhat) / np.where(np.abs(Lhat) < 1e-9, np.nan, np.abs(Lhat))
    return np.sum(rel > THRESH, axis=1)


def inject(P, kind, idx0, width, rng):
    Q = P.copy()
    sl = slice(idx0, min(idx0 + width, P.shape[0]))
    if kind == "I1_jump":
        d = rng.normal(size=3)
        d = d / np.linalg.norm(d) * 0.150
        Q[sl, 8] = Q[sl, 8] + d
    elif kind == "I2_loss":
        Q[sl, 8] = np.nan
    elif kind == "I3_scale":
        w = P[sl, 0:1, :]
        Q[sl] = w + 1.5 * (P[sl] - w)
    elif kind == "I4_collapse":
        Q[sl, 8] = P[sl, 0]
    return Q, sl


def main():
    sessions = [d for d in sorted(os.listdir(ROOT)) if os.path.isdir(os.path.join(ROOT, d))]
    rng = np.random.default_rng(20261002)

    # --- 비장애 개발군에서만 적합 ---
    healthy = None
    for d in sessions:
        m = glob.glob(os.path.join(ROOT, d, "*_metadata.json"))
        if m and json.load(io.open(m[0], encoding="utf-8-sig")).get("subject", {}).get("group") != "Patient":
            healthy = d
            break
    fits = {h: {"fixed": None, "coef": None} for h in ("Left", "Right")}
    for h in ("Left", "Right"):
        wins = load_windows(os.path.join(ROOT, healthy), h) if healthy else []
        if not wins:
            continue
        Ls, Ts = [], []
        for w in wins:
            Ls.append(seg_lengths(w["P"])); Ts.append(finger_theta(w["P"]))
        L = np.vstack(Ls); T = np.vstack(Ts)
        fits[h]["fixed"] = np.nanmedian(L, axis=0)
        coef = np.full((len(SEGMENTS), 3), np.nan)
        for j, seg in enumerate(SEGMENTS):
            fg = SEG_FINGER[seg]
            k = ("Thumb", "Index", "Middle", "Ring", "Pinky").index(fg)
            x, y = T[:, k], L[:, j]
            ok = np.isfinite(x) & np.isfinite(y)
            if ok.sum() >= 30:
                A = np.vstack([np.ones(ok.sum()), x[ok], x[ok] ** 2]).T
                coef[j] = np.linalg.lstsq(A, y[ok], rcond=None)[0]
        fits[h]["coef"] = coef

    print("=" * 112)
    print("분절 규칙 실패 유형 주입 검증 — 검출률 (규칙×주입유형×집단), 오검출률 병기")
    print("=" * 112)
    print("B계수 적합에 쓴 자료:", healthy, "(동일 세션에서 평가 → 순환, 오검출 낙관)")

    res = {"provenance": {
        "threshold": THRESH, "min_seg": MIN_SEG, "inject_width_frames": 8,
        "fit_session": healthy, "circularity": "B 계수를 비장애 1세션에서 적합·동평가 → 오검출 낙관",
        "injection_types": ["I1_jump", "I2_loss", "I3_scale", "I4_collapse"],
    }, "detection": {}, "false_alarm": {}, "detail": {}}

    kinds = ["I1_jump", "I2_loss", "I3_scale", "I4_collapse", "NONE"]
    for d in sessions:
        sd = os.path.join(ROOT, d)
        m = glob.glob(os.path.join(sd, "*_metadata.json"))
        grp = (json.load(io.open(m[0], encoding="utf-8-sig")).get("subject", {}) or {}).get("group") if m else None
        gt = "Patient" if grp == "Patient" else "Healthy"
        for hand in ("Left", "Right"):
            wins = load_windows(sd, hand)
            if not wins:
                continue
            for kind in kinds:
                det = []
                for wi, w in enumerate(wins):
                    P = w["P"]
                    if kind == "NONE":
                        Q, sl = P, slice(0, 0)
                    else:
                        idx0 = max(1, int(0.35 * P.shape[0]))
                        Q, sl = inject(P, kind, idx0, 8, rng)
                    L = seg_lengths(Q)
                    T = finger_theta(Q)
                    # 현행
                    v_fixed = violations(L, fits[hand]["fixed"])
                    # B안
                    Lhat = np.full_like(L, np.nan)
                    for j, seg in enumerate(SEGMENTS):
                        k = ("Thumb", "Index", "Middle", "Ring", "Pinky").index(SEG_FINGER[seg])
                        a = fits[hand]["coef"][j]
                        if np.isfinite(a).all():
                            Lhat[:, j] = a[0] + a[1] * T[:, k] + a[2] * T[:, k] ** 2
                    v_b = violations(L, Lhat)
                    if kind == "NONE":
                        det.append((int(np.sum(v_fixed >= MIN_SEG)), int(np.sum(v_b >= MIN_SEG)), P.shape[0]))
                    else:
                        fs, bs = v_fixed[sl], v_b[sl]
                        # 결측으로 분절을 계산할 수 없는 프레임은 '판정보류'로 따로 센다
                        unus = int(np.sum(~np.isfinite(L[sl]).any(axis=1)))
                        det.append((int(np.any(fs >= MIN_SEG)), int(np.any(bs >= MIN_SEG)), unus))
                res["detail"].setdefault(d, {}).setdefault(hand, {})[kind] = det
                if kind == "NONE":
                    nfr = sum(x[2] for x in det)
                    res["false_alarm"]["%s|%s" % (gt, hand)] = {
                        "n_frames": nfr,
                        "fixed_frame_rate": sum(x[0] for x in det) / max(nfr, 1),
                        "B_frame_rate": sum(x[1] for x in det) / max(nfr, 1)}
                else:
                    res["detection"]["%s|%s|%s" % (gt, hand, kind)] = {
                        "n_trials": len(det),
                        "fixed": sum(x[0] for x in det) / len(det),
                        "B": sum(x[1] for x in det) / len(det),
                        "unusable_any": sum(1 for x in det if x[2] > 0) / len(det)}

    print()
    print("■ 주입 검출률 (시행 단위, 0.5초 주입)")
    print("%-34s %6s %9s %9s %9s" % ("집단|손|주입", "시행", "현행", "B안", "판정보류(결측)"))
    for k in sorted(res["detection"]):
        v = res["detection"][k]
        print("%-34s %6d %9.2f %9.2f %9.2f" % (k, v["n_trials"], v["fixed"], v["B"], v["unusable_any"]))
    print()
    print("■ 정상 구간 오검출 (프레임 단위)")
    print("%-22s %9s %12s %10s" % ("집단|손", "프레임", "현행 오검출", "B안 오검출"))
    for k in sorted(res["false_alarm"]):
        v = res["false_alarm"][k]
        print("%-22s %9d %12.4f %10.4f" % (k, v["n_frames"], v["fixed_frame_rate"], v["B_frame_rate"]))

    io.open(OUT, "w", encoding="utf-8").write(json.dumps(res, ensure_ascii=False, indent=2, default=str))
    print()
    print("JSON →", OUT)


if __name__ == "__main__":
    main()
